    sb.writeln(userReq.trim().isEmpty ? '（用户未填写，请直接生成初稿）' : userReq.trim());
    sb.writeln();
    _writeBibleBlock(sb, bible); // v621
    if (mapTable.isNotEmpty) {
      sb.writeln('【改编映射表】');
      sb.writeln(mapTable);
