    return sb.toString();
  }

  /// buildArcSummaryEntrySystemPrompt — 弧线总结条目（逐场景模式的阶段A）
  static String buildArcSummaryEntrySystemPrompt(bool deduce,
      {bool hasRequirements = true}) {
    if (!hasRequirements) {
      // v217：无改编要求=原样整理模式——分析数据直接转条目，零改写
      return '你是SillyTavern世界书专家。用户**没有改编要求**——把提供的弧线分析数据原样整理为弧线总结条目。\n\n'
          '## 铁律：零改动\n'
          '概述/世界观/人设/冲突/伏笔等全部内容**原样搬运**分析数据（可以整理格式，但一个字的实质内容都不许改）。\n'
          '人设不需要映射表——直接用原著人名。禁止"优化""润色""补充"——原文是什么就写什么。\n\n'
          '## 条目content结构（⚠️只有弧线总结，禁止场景/分镜）\n'
          '弧线N概述：（直接用分析数据的概述）\n'
          '【世界观设定】按用户数据里的worldbuilding_facts逐条整理（原样搬运rule+function；没有facts的体系才写"本弧线未涉及"）\n'
          '【人设】直接列原著角色：姓名+身份+定位+性格特征（原样搬运）\n'
          '【矛盾冲突】【伏笔】【弧线功能】【不可逆变化】【情绪曲线】【作者脑洞】（全部原样搬运）\n'
          '【笔墨癖好】数据里有ink_hobby就原样搬运（痴迷点/快进点/啰嗦点），没有则省略该行\n'
          '【文风指纹】数据里有style_dna就原样搬运（原作者笔法量化指标行），没有则省略该行\n'
          '⚠️ 每个结构标记必须输出完整内容——标记行下面紧跟实质内容行（禁止空块、禁止只输出标记行）；每个标记只出现一次。\n\n'
          '## 输出\n'
          '输出JSON：{"entries":[{"comment":"弧线N：标题","key":["弧线N"],"content":"上述结构内容","constant":false,"order":100}]}\n'
          '⚠️ comment里的标题=原著弧线标题原样。';
    }
    return '你是SillyTavern世界书专家。生成一条弧线总结条目（不含场景和分镜）。\n\n'
        '## 条目content结构（⚠️只有弧线总结，禁止场景/分镜）\n'
        '弧线N概述：（50-150字）\n'
        '【世界观设定】10个体系每个必须各写一条（未涉及写"本弧线未涉及"），格式：[体系名] 规则（功能：目的）：经济体系/修炼境界体系/功法技能体系/社会政治体系/地理世界体系/法宝物品体系/丹药灵草体系/种族生物体系/组织势力体系/历史传说体系\n'
        '【人设】区结构：第一部分=角色名单（每行"原著名（定位）"，列全全部原著角色，主角必须在列）；第二部分=各角色详情（原姓名+身份+定位+性格特征）\n'
        '⚠️ 角色名单是后续所有场景生成的人名基准，必须列全\n'
        '⚠️ 全书统一规则：条目与人设一律使用原著原名（人名/地名/宗派/功法/物品等所有专有名词原样保留，禁止起新名、禁止替换）——改名由名称映射表在输出层统一处理，条目里出现任何新名都是错误\n'
        '【矛盾冲突】冲突类型+描述\n'
        '⚠️ 改编分层原则（骨架不变·血肉重写）：\n'
        '  · 【人设】保持原著不变——姓名/身份/定位/性格内核原样（只允许按声明的人物行为模式卡调整行为表达，性格与人物关系不改）\n'
        '  · 【弧线功能】【不可逆变化】【情绪曲线】保持原著叙事功能不变（这是弧线的骨架）\n'
        '  · 【世界观设定】【矛盾冲突】【伏笔】【作者脑洞】按改编要求重写具体内容（新设定下的等价表达——冲突对象/伏笔载体/脑洞呈现随新情境变，种收关系和功能不变）\n'
        '【伏笔】伏笔内容+种下位置+预期回报\n'
        '【弧线功能】叙事功能\n'
        '【不可逆变化】弧线结束后的永久性转折\n'
        '【情绪曲线】情绪轨迹如"低谷→希望→兴奋→满足"\n'
        '【作者脑洞】核心脑洞类别：具体内容（2-4条）\n'
        '【笔墨癖好】痴迷点：xxx（跨场景反复停留的内容类型——作者的执念）/快进点：xxx（一笔带过）/啰嗦点：xxx（反复交代的细节）——数据里有就原样/推演转换，没有则从场景列表归纳\n'
        '【文风指纹】数据里有style_dna就原样搬运（原作者笔法量化指标行——句长/短句占比/动词密度/对话占比/形容词频率/的字密度/语气词/比喻密度/段落均长/标点/句类四态），没有则省略该行\n'
        '⚠️ 每个结构标记必须输出完整内容——标记行下面紧跟实质内容行（禁止空块、禁止只输出标记行）；每个标记只出现一次。entries数组必须恰好1个元素（概述+九件套全部合并在这一个content里，禁止拆成多个条目）。\n\n'
        '## 输出\n'
        '输出JSON：{"entries":[{"comment":"弧线N：标题","key":["弧线N","角色名"],"content":"上述结构内容","constant":false,"order":100}]}\n'
        '⚠️ comment必须为"弧线N：新故事标题"格式。${deduce ? "推演模式：剧情内容按新设定推演，与原著情节零重叠，但⚠️ 全书统一规则：条目与人设一律使用原著原名（人名/地名/宗派/功法/物品等所有专有名词原样保留，禁止起新名、禁止替换）——改名由名称映射表在输出层统一处理，条目里出现任何新名都是错误——推演的是事件/冲突/设定层，名称层保持原名。" : "换皮模式：按改编要求转换，结构比例对应原著。用户没给具体要求时：执行基础换皮——冲突形式/背景设定转换，但⚠️ 全书统一规则：条目与人设一律使用原著原名（人名/地名/宗派/功法/物品等所有专有名词原样保留，禁止起新名、禁止替换）——改名由名称映射表在输出层统一处理，条目里出现任何新名都是错误，句式结构与语感锚原样保留。"}';
  }

  /// buildArcSummaryEntryUserPrompt — 弧线总结条目的user prompt
  static String buildArcSummaryEntryUserPrompt(
    dynamic arcItem,
    String requirements,
    String declaration,
    int sceneCount,
    int arcNumber, [
    String bible = '', // v621：故事圣经（弧线2+注入，弧线1时圣经尚未生成）
  ]) {
    final arc = arcItem is Map ? arcItem : <String, dynamic>{};
    final analysis = arc['analysis'] is Map ? arc['analysis'] as Map : {};
    final arcData = analysis['arc'] is Map ? analysis['arc'] as Map : {};
    final sb = StringBuffer();
    sb.writeln('## 任务：生成弧线总结条目（该弧线共$sceneCount个场景，场景和分镜由后续步骤单独生成）');
    sb.writeln();
    if (requirements.isNotEmpty) {
      sb.writeln('## 用户改编要求');
      sb.writeln(requirements);
      sb.writeln();
    }
    if (declaration.isNotEmpty) {
      sb.writeln('## 弧线改编声明（必须遵守）');
      sb.writeln(declaration);
      sb.writeln();
    }
    _writeBibleBlock(sb, bible); // v621
    sb.writeln('## 原著弧线数据');
    sb.writeln('⚠️ 本条目弧线编号：N=$arcNumber——输出中所有"弧线N"字样必须用$arcNumber替换：comment="弧线$arcNumber：标题"，key含"弧线$arcNumber"，content第一行="弧线$arcNumber概述：..."。禁止写成其他编号');
    sb.writeln('弧线标题：${arcData['title'] ?? arc['title'] ?? ''}');
    final sum = arcData['summary'];
    if (sum != null && sum.toString().isNotEmpty) sb.writeln('弧线概述：$sum');
    final md = arcData;
    [
      'characters',
      'conflicts',
      'foreshadowing',
      'arc_functions',
      'irreversible_changes',
      'emotional_curve',
      'author_fantasy',
      'ink_hobby', // v219：笔墨癖好（作者注意力画像）
      'style_dna', // v640：文风指纹（【文风指纹】行的数据源）
      'worldbuilding_facts', // v227：世界观facts（【世界观设定】的数据源）
    ].forEach((k) {
      final v = md[k];
      if (v != null && v.toString().isNotEmpty && v.toString() != '[]') {
        sb.writeln('$k：$v');
      }
    });
    final scenes = arcData['scenes'] as List? ?? [];
    if (scenes.isNotEmpty) {
      sb.writeln('场景列表（仅标题，供人设/冲突参照）：');
      for (var i = 0; i < scenes.length; i++) {
        final sc = scenes[i] is Map ? scenes[i] as Map : {};
        sb.writeln('场景${i + 1}：${sc['name'] ?? ''}');
      }
    }
    sb.writeln();
    sb.writeln('请生成该弧线的总结条目JSON（只有弧线总结十件套，无场景无分镜）。');
    return sb.toString();
  }

  /// buildSceneFrameSystemPrompt — 单场景框架条目（阶段B）
  static String buildSceneFrameSystemPrompt(bool deduce,
      {bool hasRequirements = true, bool jsonMode = false}) {
    if (!hasRequirements) {
      // v217：无改编要求=原样整理模式
      return '你是SillyTavern世界书专家。用户**没有改编要求**——把原著场景数据原样整理为场景框架条目。\n\n'
          '## 铁律：零改动\n'
          '场景标题=原著场景名原样；概述=原著场景概述**逐字搬运**；章节范围原样照抄。\n'
          '禁止"优化""润色""改写""重新创作"——原文是什么就写什么。\n\n'
          '## 条件content结构（⚠️只有场景框架两行，禁止分镜）\n'
          '场景N：原著场景名（第X-Y章）←章节范围原样照抄\n'
          '概述：原著场景概述逐字搬运\n\n'
          '## 输出\n' +
          (jsonMode
              ? '输出JSON（恰好一个对象）：{"content":"场景N：原著场景名（第X-Y章）\\n概述：原著场景概述逐字搬运"}——content字段就是上述两行文本（\\n是换行转义），禁止其它字段、禁止JSON数组\n'
              : '直接输出纯文本两行（⚠️禁止JSON、禁止引号键值对、禁止markdown围栏）：\n'
                '场景N：原著场景名（第X-Y章）\n'
                '概述：原著场景概述逐字搬运');
    }
    return '你是SillyTavern世界书专家。为单个场景生成场景框架条目（场景头+概述，不含分镜）。\n\n'
        '## 条目content结构（⚠️只有场景框架两行，禁止分镜）\n'
        '场景N：改编后场景标题（第X-Y章）\n'
        '概述：本场景改编后事件链的完整陈述（不限字数）\n\n'
        '## ⚠️ 概述硬性要求\n'
        '⚠️ 概述=本场景的完整改编事实清单，是后续分镜的唯一内容基准：\n'
        '- 用户改编要求里涉及本场景的每个设定细节——谁在谁的摊位卖货、责任归属、谁演示了什么（真品还是仿品）、掉包/问责/善后的因果顺序——必须逐条写进概述，禁止压缩成一句标题式摘要\n'
        '- 宁多勿漏：概述写300字也不许丢一个改编设定细节（分镜将从它逐镜生长，概述里没有的细节分镜就不会有）\n'
        '概述必须是全新创作的改编后内容——描述新故事里这个场景发生了什么（⚠️人名/地名等专名仍用原著原名，与全书命名规则一致，改名由映射表输出层处理）。\n'
        '禁止照抄原著概述（只换情节其余照抄也算照抄）——原著概述只用于理解场景功能。\n'
        '⚠️ 概述从弧线总结条目生长：改编后的世界观/人设/冲突（含冲突对象锁定）/伏笔是既成事实，概述里的新内容必须与它们一致——禁止发明零件里没有的新设定。\n'
        '正例：原著"张三在坊市低价淘到灵剑"→新"张三在旧货摊砍价捡漏芯片母板"（功能等价，人名保持原名）\n'
        '反例：原著概述原样输出或仅替换人名——禁止。\n\n'
        '## ⚠️ 章节范围硬性要求\n'
        '场景标题括号内的章节范围必须**原样照抄**原著该场景的章节范围（用户提供的数据里有），\n'
        '一个字都不许改（"第3-5章"就是"第3-5章"，禁止自编新数字、禁止省略括号）。\n'
        '改编只换内容不换章节映射——章节范围是定位锚点，丢失会导致后续定位错乱。\n\n'
        '## 输出\n' +
        (jsonMode
            ? '输出JSON（恰好一个对象）：{"content":"场景N：改编后场景标题（第X-Y章）\\n概述：（完整事件链，不限字数）"}——content字段就是上述两行文本（\\n是换行转义），禁止其它字段、禁止JSON数组\n'
            : '直接输出纯文本两行（⚠️禁止JSON、禁止引号键值对、禁止markdown围栏）：\n'
              '场景N：改编后场景标题（第X-Y章）\n'
              '概述：（完整事件链陈述，不限字数）\n') +
        '${deduce ? "推演模式：场景内容按新设定推演，与原著零重叠——概述写新故事内容。" : "换皮模式：按改编要求转换场景，结构对应原著场景——概述写改编后内容。"}\n'
        '⚠️ 标题和概述里的角色一律用原著原名（与user侧全书命名规则一致——A方案：生成端全原名，改名由名称映射表在输出层统一处理），禁止发明新名。';
  }

  /// buildSceneFrameUserPrompt — 单场景框架的user prompt
  /// v214：context参数=九件套+已改编场景框架（连贯性锚点——
  /// 新场景必须接着已改编的世界写，不是接着原著写）
  static String buildSceneFrameUserPrompt(
    dynamic arcItem,
    int sceneIdx,
    String requirements,
    String declaration, {
    String arcContext = '',
    String adaptedFrames = '',
    bool deduce = false,
    List<Map<String, dynamic>>? castRoles,
    String bible = '', // v621：故事圣经
  }) {
    final arc = arcItem is Map ? arcItem : <String, dynamic>{};
    final analysis = arc['analysis'] is Map ? arc['analysis'] as Map : {};
    final arcData = analysis['arc'] is Map ? analysis['arc'] as Map : {};
    final scenes = arcData['scenes'] as List? ?? [];
    final sc = sceneIdx < scenes.length && scenes[sceneIdx] is Map
        ? scenes[sceneIdx] as Map
        : {};
    final sb = StringBuffer();
    sb.writeln('## 任务：生成场景${sceneIdx + 1}框架条目（分镜由后续步骤生成）');
    _writeBibleBlock(sb, bible); // v621
    sb.writeln();    sb.writeln('⚠️ 全书统一命名规则（最高优先级）：场景标题/概述/各维度值一律使用原著原名指代角色/地点/组织/功法/物品等专有名词，禁止为配合新世界观发明任何新名——设定层可以修仙化/换背景，名称层保持原名（改名由名称映射表在输出层统一处理）。若用户改编要求与新命名规则冲突，命名仍保持原名');
    sb.writeln();
    if (requirements.isNotEmpty) {
      sb.writeln('## 用户改编要求');
      sb.writeln(requirements);
      sb.writeln();
    }
    if (declaration.isNotEmpty) {
      sb.writeln('## 弧线改编声明（场景标题和概述必须符合声明的场景功能声明）');
      sb.writeln(declaration);
      sb.writeln();
    }
    // v214/v216：弧线总结上下文（有人设卡=改编后总结全文：新世界观+人设映射表+
    // 冲突伏笔等；无人设卡=原著九件套兜底）
    if (arcContext.isNotEmpty) {
      sb.writeln('## 弧线既成事实（⚠️改编基准：世界体系/角色名（含映射表）/冲突/伏笔');
      sb.writeln('必须与本数据一致；后续场景是它的展开，不是另起炉灶）');
      sb.writeln(arcContext);
      sb.writeln();
    }
    // v214：已改编场景框架（既成事实——新场景必须衔接，不得另起炉灶）
    if (adaptedFrames.isNotEmpty) {
      sb.writeln('## 已改编的前序场景（既成事实：本场景必须与之连贯——');
      sb.writeln('人物名/事件/道具/伏笔状态一律沿用，禁止与本区内容矛盾）');
      sb.writeln(adaptedFrames);
      sb.writeln();
    }
    // v257：推演模式框架隐内容层——场景名/概述/原著焦点节奏全是内容层，
    // 不进prompt（推演从弧线总结+声明+新设定构思，眼前无原著情节可抄）。
    // 只发章节范围（定位锚点）+分镜数量+各镜功能抽象（功能等价参考）
    if (deduce) {
      sb.writeln('## 场景${sceneIdx + 1}功能定位（推演模式——无原著情节，');
      sb.writeln('场景标题和概述从弧线既成事实+声明+前序场景推演全新内容）');
      if ((sc['chapter_range'] ?? '').toString().isNotEmpty) {
        sb.writeln('章节范围：${sc['chapter_range']}（⚠️新场景标题括号内必须原样照抄这个范围）');
      }
      final orgShots = sc['shots'] as List? ?? [];
      if (orgShots.isNotEmpty) {
        sb.writeln('分镜数：${orgShots.length}镜（功能完整覆盖即可，数量可调整）。各镜功能：');
        for (var oi = 0; oi < orgShots.length; oi++) {
          final sh = orgShots[oi] is Map ? orgShots[oi] as Map : {};
          final abst = sh['abstract']?.toString() ?? '';
          // v258：注意力焦点抽象（继承原著'先看谁'的注意力轨迹）
          final focusAbstracted = _abstractFocus(
            sh['focus']?.toString() ?? '',
            castRoles ?? const [],
          );
          sb.writeln(
            '  ${oi + 1}. ${abst.isNotEmpty ? abst : sh['intent'] ?? '（缺失）'}'
            '${focusAbstracted.isNotEmpty ? '｜注意力：$focusAbstracted' : ''}',
          );
        }
        sb.writeln('（新概述需覆盖同等完整的叙事过程，禁止只写开头）');
      }
      sb.writeln();
      sb.writeln('请生成该场景的框架条目（场景头+概述两行，无分镜）。');
      return sb.toString();
    }
    sb.writeln('## 原著场景${sceneIdx + 1}数据（⚠️仅供理解场景功能——概述禁止照抄，人名禁止沿用）');
    sb.writeln('场景名：${sc['name'] ?? ''}');
    if ((sc['summary'] ?? '').toString().isNotEmpty) {
      sb.writeln('概述：${sc['summary']}');
    }
    if ((sc['chapter_range'] ?? '').toString().isNotEmpty) {
      sb.writeln('章节范围：${sc['chapter_range']}（⚠️新场景标题括号内必须原样照抄这个范围）');
    }
    // v216：分镜骨架精简版（每镜一行）——新概述必须覆盖该场景的
    // 完整叙事节奏（起-转-合），不能只写第一步
    final orgShots = sc['shots'] as List? ?? [];
    if (orgShots.isNotEmpty) {
      sb.writeln('原著分镜节奏（${orgShots.length}镜——新概述需覆盖同等完整的过程，禁止只写开头）：');
      for (var oi = 0; oi < orgShots.length; oi++) {
        final sh = orgShots[oi] is Map ? orgShots[oi] as Map : {};
        sb.writeln(
          '  ${oi + 1}. ${sh['focus'] ?? ''}[${sh['shot_type'] ?? ''}]→${sh['intent'] ?? ''}',
        );
      }
    }
    sb.writeln();
    sb.writeln('请生成该场景的框架条目JSON（场景头+概述两行，无分镜）。');
    return sb.toString();
  }

  /// v258：焦点注意力抽象——原焦点的原著人名替换为定位称谓（'魏索'→
  /// '主角'，配角→'配角·定位词'），保留注意力轨迹（先看谁/谁和谁互动/
  /// 何时切世界观）但不含原著具体内容。确定性代码变换。
  /// 投放信息不抽象（内容层信息量太大，人名替换收益低）——靠功能抽象+注意力焦点双锚
  static String _abstractFocus(String focus, List<Map<String, dynamic>> castRoles) {
    if (focus.isEmpty) return '';
    var out = focus;
    // 人名→定位（长名优先防'魏索'匹配'魏索然'子串）
    final sorted = [...castRoles]..sort(
      (a, b) => (b['name']?.toString() ?? '').length.compareTo(
        (a['name']?.toString() ?? '').length,
      ),
    );
    for (final r in sorted) {
      final name = r['name']?.toString() ?? '';
      if (name.isEmpty || name.length < 2) continue;
      final role = r['role']?.toString() ?? '';
      if (role.isEmpty) continue;
      if (out.contains(name)) {
        out = out.replaceAll(name, role);
      }
    }
    return out;
  }

  /// buildSceneShotFillUserPrompt — 单场景分镜填充的user prompt（阶段C）
  /// v215：cast参数=改编后人设卡（角色名映射基准——主角是谁/配角是谁，
  /// 原著主角名必须映射到新主角名，防止AI就近映射错角色）
  static String buildSceneShotFillUserPrompt({
    required String entryContent,
    required Map<String, dynamic> scene,
    required int sceneIdx,
    String declaration = '',
    String requirements = '',
    String cast = '',
    bool deduce = false,
    List<Map<String, dynamic>>? castRoles,
    int? onlyShotIdx, // v593：单镜改编——只输出该镜
    String prevShots = '', // v593→v620：场景内前面全部已改编镜（衔接锚）
    String prevSceneTail = '', // v620：上一场景结尾已改编镜（跨场景衔接锚）
    String bible = '', // v621：故事圣经
  }) {
    final sb = StringBuffer();
    sb.writeln('⚠️ 全书统一命名规则（最高优先级）：场景标题/概述/各维度值一律使用原著原名指代角色/地点/组织/功法/物品等专有名词，禁止为配合新世界观发明任何新名——设定层可以修仙化/换背景，名称层保持原名（改名由名称映射表在输出层统一处理）。若用户改编要求与新命名规则冲突，命名仍保持原名');
    sb.writeln();
    _writeBibleBlock(sb, bible); // v621
    sb.writeln('## 已生成的改编后场景条目（新场景内容以它为准）');
    sb.writeln(entryContent);
    sb.writeln();
    if (cast.isNotEmpty) {
      sb.writeln('## 已改编的弧线总结（⚠️既成事实，分镜必须在其上生长——');
      sb.writeln('新世界观/新人设卡（含映射表）/新冲突/新伏笔一律沿用此处内容）');
      sb.writeln(cast);
      sb.writeln();
      sb.writeln('⚠️ 人名纪律（A方案，最高优先级）：分镜里所有人物/地点/物品一律用**原著名**指称——人设卡/映射表只用于判断角色定位对应（原著分镜里"主角"的动作由卡中定位为主角的那位原著角色执行），禁止把映射表右列的新名写进分镜——新名由输出层统一替换，分镜里出现任何新名=错误');
      sb.writeln();
    }
    if (declaration.isNotEmpty) {
      sb.writeln('## 弧线改编声明（必须严格遵守——禁令和行为模式）');
      sb.writeln(declaration);
      sb.writeln();
    }
    if (requirements.isNotEmpty) {
      sb.writeln('## 用户改编要求');
      sb.writeln(requirements);
      sb.writeln();
    }
    // v257：推演模式骨架隐内容层——原著具体情节（场景名/概述/焦点/投放
    // 信息）不进prompt（"眼前的原文素材诱惑远大于禁令约束"=AI就近映射
    // 惯性，推演比换皮抄得多的根因）。类型层8维（镜头/视角/意图/转场/
    // 篇幅/节奏/语感/笔墨）+功能抽象照发——推演信息量够，原著内容零暴露
    final shots = scene['shots'] as List? ?? [];
    if (deduce) {
      sb.writeln('## 原著场景${sceneIdx + 1}功能骨架（结构抽象，无原著情节——');
      sb.writeln('具体内容必须从功能抽象+新设定推演，禁止编造"类似原著"的情节）');
      sb.writeln('场景${sceneIdx + 1}（${scene['chapter_range'] ?? ''}，${shots.length}个分镜——功能完整覆盖即可，数量可调整）');
      for (var shi = 0; shi < shots.length; shi++) {
        final sh = shots[shi] is Map ? shots[shi] as Map : {};
        final parts = <String>[
          if ((sh['shot_type'] ?? '').toString().isNotEmpty)
            '原著镜头：${sh['shot_type']}（参考，需功能等价替换）',
          if ((sh['pov'] ?? '').toString().isNotEmpty)
            '原著视角：${_abstractFocus(sh['pov'].toString(), castRoles ?? const [])}（参考，需功能等价替换）',
          if ((sh['intent'] ?? '').toString().isNotEmpty)
            '意图：${sh['intent']}（继承）',
          if ((sh['transition'] ?? '').toString().isNotEmpty)
            '转场：${sh['transition']}（继承）',
          if ((sh['length'] ?? '').toString().isNotEmpty)
            '篇幅：${sh['length']}（继承）',
          if ((sh['prose_style'] ?? '').toString().isNotEmpty)
            '节奏：${sh['prose_style']}（继承）',
        ];
        sb.write('分镜${shi + 1}');
        if (parts.isNotEmpty) sb.write('｜${parts.join('｜')}');
        sb.writeln();
        // v258：注意力轨迹——焦点抽象映射（原焦点'魏索'→'主角（新主角名执行）'，
        // 原焦点'女配'→'同定位新配角'）——继承原著'先看谁/何时切世界观'的注意力
        // 倾向，具体内容AI推演。确定性代码变换不靠AI（用户洞察：AI没有注意力
        // 直觉，把'写什么'全交给AI=相机乱拍）
        final focusAbstracted = _abstractFocus(
          sh['focus']?.toString() ?? '',
          castRoles ?? const [],
        );
        if (focusAbstracted.isNotEmpty) {
          sb.writeln('  注意力焦点（抽象）：$focusAbstracted');
        }
        sb.writeln('  功能：${sh['abstract'] ?? '（缺失，按意图提炼）'}');
        // v226语感/笔墨：类型层作者癖好量化——推演必须继承（v257补进骨架，
        // 此前旧骨架块漏这两维=新维度落地全库清剿法漏网点）
        final voice = sh['voice']?.toString() ?? '';
        sb.writeln('  语感锚：${voice.isNotEmpty ? voice : '（旧数据缺失——按新设定同等腔调设计，禁止文艺加戏）'}');
        final ink = sh['ink']?.toString() ?? '';
        sb.writeln('  笔墨配额：${ink.isNotEmpty ? ink : '（旧数据缺失——按功能主次分配，主要内容占六成以上）'}');
      }
      sb.writeln();
      sb.writeln('请为已生成条目中的每个新场景填充分镜明细（推演模式：从功能骨架+新场景内容+声明推演全新具体情节，每镜11维齐全）。');
      return sb.toString();
    }
    sb.writeln('## 原著场景${sceneIdx + 1}分镜骨架（逐镜转换的结构参照）');
    sb.writeln('场景名：${scene['name'] ?? ''}');
    if ((scene['summary'] ?? '').toString().isNotEmpty) {
      sb.writeln('概述：${scene['summary']}');
    }
    for (var shi = 0; shi < shots.length; shi++) {
      final sh = shots[shi] is Map ? shots[shi] as Map : {};
      sb.writeln('原著分镜${shi + 1}：');
      sb.writeln('  焦点：${sh['focus'] ?? ''}');
      sb.writeln('  镜头类型：${sh['shot_type'] ?? ''}');
      sb.writeln('  视角：${sh['pov'] ?? ''}');
      sb.writeln('  投放信息：${sh['info'] ?? ''}');
      sb.writeln('  意图：${sh['intent'] ?? ''}');
      sb.writeln('  转场：${sh['transition'] ?? ''}');
      sb.writeln('  篇幅：${sh['length'] ?? ''}');
      sb.writeln('  文笔节奏：${sh['prose_style'] ?? ''}');
      // v218：语感锚（旧数据无voice时提示AI从原著其它行自行锚定语感）
      sb.writeln('  语感锚：${(sh['voice'] ?? '').toString().isNotEmpty ? sh['voice'] : '（旧数据缺失——从该分镜的焦点/投放信息自行判断原文腔调，按同等腔调改写，禁止文艺加戏）'}');
      // v219：笔墨配额
      sb.writeln('  笔墨配额：${(sh['ink'] ?? '').toString().isNotEmpty ? sh['ink'] : '（旧数据缺失——按焦点与意图判断主次，主要内容占六成以上）'}');
      sb.writeln('  功能抽象：${sh['abstract'] ?? '（缺失，按焦点提炼）'}');
    }
    sb.writeln();
    sb.writeln();
    if (onlyShotIdx != null) {
      sb.writeln('## 本次任务（v620单镜逐维改编）');
      sb.writeln('只改编输出【分镜${onlyShotIdx + 1}】这一个分镜块。');
      sb.writeln();
      sb.writeln('## 逐维推演（禁止敷衍——每个维度先回答"改编要求下这维该怎么改"再落笔）');
      sb.writeln('- 焦点(Focus)：本镜改编后聚焦谁/什么？必须服务场景改编要求的冲突，禁止就近映射原著');
      sb.writeln('- 投放信息(Info)：本镜要给读者投放什么新信息？30字内抽象陈述句');
      sb.writeln('- 镜头类型/视角：谁的戏？什么拍法最服务本镜冲突？');
      sb.writeln('- 意图/转场：与上一镜的因果衔接处在哪？怎么自然过渡？');
      sb.writeln('- 篇幅/文笔节奏/语感/笔墨：按本镜新内容的权重重新分配，禁止照抄原著数值');
      sb.writeln('- 功能抽象(Abstract)：功能语义保留，对象词必须换成改编后对应物');
      sb.writeln('⚠️ 原著骨架值只是"这镜承担什么功能"的参照——任何维度值与原著雷同且非刻意保留=偷懒，重写');
      sb.writeln();
      sb.writeln('## 输出前自检（不达标自己重写后再输出）');
      sb.writeln('1. 拧巴检查：本镜情节与前镜成品是否连贯？有没有逻辑断裂、重复、人设拧巴？');
      sb.writeln('2. 落实检查：场景改编要求涉及本镜的每个事实是否已正确体现？冲突对象是否为改编后对象？');
      sb.writeln('3. 越界检查：有没有原著没写的动作细节/道具/神态被凭空添加（文艺腔加戏）？');
      if (prevShots.trim().isNotEmpty) {
        sb.writeln();
        sb.writeln('## 本场景前镜已改编成品（衔接锚——本镜的入场/转场必须与它连贯，禁止情节断裂或重复）');
        sb.writeln(prevShots.trim());
      }
      if (prevSceneTail.trim().isNotEmpty) {
        sb.writeln();
        sb.writeln('## 上一场景结尾已改编分镜（跨场景衔接锚——本镜是跨场景入场，必须与前场景结尾自然承接）');
        sb.writeln(prevSceneTail.trim());
      }
      sb.writeln();
      sb.writeln('请只输出分镜${onlyShotIdx + 1}单镜块。');
    }
    return sb.toString();
  }

  /// buildShotFillSystemPrompt — 填充分镜（两步制第二步）
  /// 三层参照：原分析分镜骨架（逐镜转换锚点）+已生成场景条目（新内容）+声明（转换约束）
  static String buildShotFillSystemPrompt(bool deduce,
      {bool hasRequirements = true, bool jsonMode = false}) {
    if (!hasRequirements) {
      // v217：无改编要求=原样整理模式——分镜11维度逐字搬运（v226：9→11补voice/ink）
      return '你是SillyTavern世界书整理员。用户**没有改编要求**——把原著分镜数据原样填进场景条目。\n\n'
          '## 铁律：零改动\n'
          '每个分镜的全部维度=焦点/镜头类型/视角/投放信息/意图/转场/篇幅/文笔节奏/**语感(Voice)**/**笔墨(Ink)**/功能抽象，原著分析数据有什么维度就**逐字搬运**什么维度。\n'
          '⚠️ 数据里有voice（语感锚）、ink（笔墨配额）、style（文风统计）字段时**必须输出**这几行（后续写正文的行文锚点，丢了会导致AI文艺腔加戏+平均用力）。\n'
          '人名/事件/内容原样——禁止任何"优化""润色""改写""推演"。\n'
          '分镜数量与顺序=原著原样（禁止增删合并）。\n\n'
          '## 输出格式\n' +
          (jsonMode
              ? '输出JSON（恰好一个对象）：{"content":"（全部场景的分镜文本，\\n为换行转义）"}——content字段=按场景分组的完整分镜文本，禁止其它字段、禁止JSON数组\n'
              : '（纯文本，按场景分组）\n'
                '⚠️ 输出必须是纯文本行——禁止JSON格式、禁止引号键值对（禁止把字段写成引号包裹的键值对）、禁止markdown围栏包装。\n') +
          '场景N：场景标题（章节范围原样）\n'
          '分镜M：\n'
          '焦点(Focus)：原著值逐字搬运\n'
          '镜头类型(Shot Type)：原著值逐字搬运\n'
          '视角(POV)：原著值逐字搬运\n'
          '投放信息(Info)：原著值逐字搬运\n'
          '作者意图(Intent)：原著值逐字搬运\n'
          '转场手法(Transition)：原著值逐字搬运\n'
          '篇幅(Length)：原著值逐字搬运\n'
          '文风(Style)：质感=…|标尺=量化6项|例句=…（v685三段式——原著有独立文笔节奏/语感/文风字段时合并为该行逐字搬运不丢失；只有style字段时原样搬运）\n'
          '笔墨(Ink)：原著值逐字搬运（数据有则必输出）\n'
          '功能抽象(Abstract)：原著值逐字搬运\n'
          '⚠️ 每个原著分镜一条不落全部输出。';
    }
    return '你是网文改编执行编辑。第一步已生成改编后的场景框架和弧线总结，你的任务：为每个场景填充分镜明细（9维度）。\n\n'
        '## 填充规则（逐镜转换，不是凭空创作）\n'
        '0. **人名映射铁律**：用户提供的人设卡（含"原著名→新名"映射表）是角色名唯一基准——原著分镜里"主角"的动作必须由映射表中新主角名执行，原著配角映射到同定位新配角名。判断标准=映射表的定位，不是行为相似度——禁止因配角人设与原著主角行为模式相似就互换角色\n'
        '1. **逐镜对应（结构铁律）**：每个新场景对应原著分析数据中的一个场景，该场景的原著分镜就是你的结构骨架——**分镜数量=原著该场景分镜数，第N改编镜对应第N原著镜，一一对应，禁止增删合并**（数量锁的是叙事节奏，78镜快切被合并成20镜=节奏信息丢失）。原著分镜骨架只锁"这一镜承担哪段功能"（功能位），具体内容完全按新剧情重新推演\n'
        '2. **功能抽象(Abstract)转换**：照抄原著abstract的**功能语义**（如"心理反应/战斗场面/悬念钩子"这类抽象层），但其中出现的原著专属对象词（妖兽/法器/宗门等）必须替换为改编后对应物（如声明冲突对象锁定指定的卖家/合伙人等）——"与妖兽的战斗"→"与卖家的拉扯"。abstract里出现改编后世界观中不存在的原著名词=错误\n'
        '3. **焦点(Focus)/投放信息(Info)转换**：参照已生成的新场景内容（概述+声明）推演——原著"打妖兽"在新场景是"与骗子拉扯"就写拉扯的具体焦点，⚠️禁止就近映射（如"验证法器"）\n。⚠️焦点必须有具体内容不可省略——每个分镜头行的焦点(Focus)位置必须填该分镜画面聚焦的人/物/事。⚠️投放信息(Info)必须是**抽象概括的陈述句**（如"读者得知主角对行情一无所知"，30字以内），禁止写成正文式的具体情节叙述——Info是给读者看的元信息提示，不是正文素材：禁止包含具体动作/对白/画面细节，写成可直接抄进正文的句子=错误（创作端会照抄它）\n'
        '4. **镜头类型/视角（形式层推演）**：按新场景的内容重新设计——镜头类型服务新场景的叙事节奏（对话博弈/经营算计/追责冲突各有各的拍法），视角由"该镜谁的戏"决定；原著值仅作节奏风格参照，禁止直接照搬\n'
        '5. **意图/转场/篇幅（形式层推演）**：按新场景的事件链重新设计——转场手法按新场景的镜间因果设计（怎样从上一镜自然过渡），篇幅按新内容的信息量分配（可参照原著比例但禁止照抄）\n'
        '5.5 **文风(Style)三段式（v685统一维度）**：改编镜的文风行必须输出——质感=按新内容重新推演的行文腔调（承接原著该镜语感/文笔节奏语义）；标尺=原著该镜style标尺为基准微调继承（±30%，禁抄原著值也禁凭空乱编，无则按新场景本镜内容统计设计，打斗镜短句密、铺垫镜长句疏；**固定6项且占比带%号**——弧级【文风指纹】13项指标是全弧基线禁止逐镜照抄）；例句=从新场景本镜内容摘一句最有代表性的≤20字（禁抄原著例句）。缺失文风行=创作时退回AI默认文风\n'
        '6. **遵守弧线改编声明**：声明中的场景禁令和人物行为模式卡必须严格执行\n'
        '6.5 ⚠️ **冲突对象锁定（最强约束）**：声明中每个场景的"冲突对象锁定"是本分镜冲突的裁定依据——每个分镜的矛盾冲突必须发生在声明的【改编后冲突对象】上；禁止把【原著冲突对象】（如妖兽/验法器/宗门大比）平移成本分镜的冲突。判断标准：这个分镜里主角在跟谁拉扯/对抗/博弈？答案必须是改编后对象，否则该分镜改编错误\n'
        '6.6 ⚠️ **概述=内容基准，骨架=数量基准（两者分管不同层）**：本分镜的焦点/投放信息的内容素材优先从"已生成的改编后场景概述"的情节取材——概述说清了本场景发生什么事；但**分镜的数量/顺序/边界只认原著骨架，禁止按概述重新铺分镜列表**（概述300字铺出20镜=丢节奏的错误做法）。禁止绕过概述直接把原著分镜内容平移过来换名词\n'
        '7. **零正文**：只输出结构行，不写正文段落\n'
        '8. **语感锚铁律（v218，最高优先级之一）**：原著分镜的voice只照抄**抽象三段（修饰密度|句式|语域）**，例句部分丢弃——例句仅用于理解腔调，禁止把例句文字搬进改编条目。改写focus/info等维度内容时，行文腔调必须符合语感锚——锚是"极简|短句口语|俚俗"时，你的投放信息也只能用同样糙直的口语表达，**禁止文艺腔加戏**。反例警示：原著"李大开\"诶\"一声叫住和尚"（voice=极简|短句口语|俚俗），换皮写成"李大开缓缓抬起带着扳指的手，轻声叫住了和尚"——这就是AI文艺腔灾难，禁止。原著没写的动作细节/道具/神态一律不准凭空添加。⚠️ voice例句中出现的原著对象词（妖兽/石尾壁蜥等）**仅为腔调参考**——照腔调写正文时内容必须用改编后对象，禁止把例句里的原著生物/物品写进改编后的故事\n'
        '9. **笔墨配额铁律（v219，最高优先级之一）**：新分镜的ink（笔墨配额，格式"内容A约N字·内容B约N字"）按改编后内容**重新设计**——原著ink只作注意力权重思想参照（主次分明、禁平均用力），字数分配按新场景本镜实际内容构成重新计算，禁止照抄原著数值。⚠️ intent同时是注意力令牌：intent=铺垫→克制（把爽感留给高潮分镜），intent=高潮→打透但禁止反复在同一爽点打转（一次打透换下一镜），intent=钩子→写完钩子就停手不恋战\n'
        '9.5 **笔墨癖好统摄（推演/换皮都生效）**：弧线总结里的【笔墨癖好】（痴迷点/快进点/啰嗦点）是新分镜笔墨设计的总指挥——**设计每个新分镜的ink配额时**：痴迷点类内容给大配额（这是作者执念，值得停留），快进点类内容给小配额或并入其它镜头一笔带过（哪怕它"很有料"），啰嗦点类细节允许在多个分镜重复出现。⚠️ 推演模式禁令：不许因为某个新元素在第一镜出现过（如新角色被吐槽蠢），后续分镜的ink就反复给它配额——那是就近强化不是痴迷点停留。痴迷点是对**内容类型**的偏心，不是对**具体对象**的纠缠\n'
        '\${deduce ? "9. **推演模式**：分镜内容按新设定推演，与原著零重叠——原著分镜骨架只提供结构（数量/顺序/功能），具体内容（谁做了什么）必须换成新角色新事件。禁止沿用原著的具体人名/地名/事件。voice的修饰密度和语域必须继承（新内容用同等糙度/雅度的表达），例句换成新内容的同等姿态短句" : "9. **换皮模式**：按改编要求逐镜转换原著分镜——结构对应，内容按新设定重写。voice例句里的原著元素替换为新元素但姿态不变（\"诶\"一声叫住的例句→新角色也用同款干脆的叫法）"}\n\n'
        '## 输出格式\n' +
        (jsonMode
            ? '输出JSON（恰好一个对象）：{"content":"（全部场景的分镜文本，\\n为换行转义）"}——content字段=按场景分组的完整分镜文本，禁止其它字段、禁止JSON数组\n'
            : '（纯文本，按场景分组）\n'
              '⚠️ 输出必须是纯文本行——禁止JSON格式、禁止引号键值对（禁止把字段写成引号包裹的键值对）、禁止markdown围栏包装。\n') +
        '场景N：场景标题\n'
        '分镜M：\n'
        '焦点(Focus)：该分镜画面聚焦什么人/物/事（必须填具体内容，禁止留空或省略）\n'
        '镜头类型(Shot Type)：镜头类型（必须有值）\n'
        '视角(POV)：视角\n'
        '投放信息(Info)：抽象概括的陈述句（如"读者得知主角对行情一无所知"，30字以内，禁止正文式情节叙述；行文腔调符合语感锚）\n'
        '作者意图(Intent)：xxx\n'
        '转场手法(Transition)：xxx\n'
        '篇幅(Length)：xxx\n'
        '文风(Style)：质感=行文腔调一句话定性（手法+调性，承接原著该镜语感/文笔节奏的语义按新内容重新推演）|标尺=句长N字|短句占比N%|动词密度N|对话占比N%|形容词密度N|比喻密度N（**固定6项**，占比必须带%号；原著该镜有style标尺=以此为基准按新内容微调继承±30%，无则按新场景本镜内容节奏统计设计；弧级【文风指纹】的"的"字密度/语气词频率/段落均长/标点习惯/句类四态是弧级基线专属，禁止抄进分镜维度行）|例句=从新场景本镜内容摘一句最有代表性的≤20字（禁抄原著例句）\n'
        '笔墨(Ink)：按新内容重新设计（"内容A约N字·内容B约N字"格式，分配服务本镜新内容）\n'
        '功能抽象(Abstract)：功能语义照原著abstract，对象词换成改编后对应（禁原著名词）\n'
        '\n每个场景都要填充，输出全部场景的分镜。';
  }

  /// buildShotFillUserPrompt — 填充分镜的用户提示词
  /// entryContent=第一步生成的条目content（场景+弧线总结）
  /// analysisData=原著该弧线的完整分析数据（含分镜）
  /// declaration=弧线改编声明
  static String buildShotFillUserPrompt({
    required String entryContent,
    required Map<String, dynamic> analysisData,
    String declaration = '',
    String requirements = '',
  }) {
    final sb = StringBuffer();
    sb.writeln('## 已生成的改编后条目（第一步成果——新场景内容以它为准）');
    sb.writeln(entryContent);
    sb.writeln();
    if (declaration.isNotEmpty) {
      sb.writeln('## 弧线改编声明（必须严格遵守——禁令和行为模式）');
      sb.writeln(declaration);
      sb.writeln();
    }
    if (requirements.isNotEmpty) {
      sb.writeln('## 用户改编要求');
      sb.writeln(requirements);
      sb.writeln();
    }
    sb.writeln('## 原著分析数据（分镜骨架——逐镜转换的结构参照）');
    final scenes = analysisData['scenes'] as List? ?? [];
    for (var si = 0; si < scenes.length; si++) {
      final sc = scenes[si] is Map ? scenes[si] as Map : {};
      sb.writeln('### 原著场景${si + 1}：${sc['name'] ?? ''}');
      if ((sc['summary'] ?? '').toString().isNotEmpty) {
        sb.writeln('概述：${sc['summary']}');
      }
      final shots = sc['shots'] as List? ?? [];
      for (var shi = 0; shi < shots.length; shi++) {
        final sh = shots[shi] is Map ? shots[shi] as Map : {};
        sb.writeln('原著分镜${shi + 1}：');
        sb.writeln('  焦点：${sh['focus'] ?? ''}');
        sb.writeln('  镜头类型：${sh['shot_type'] ?? ''}');
        sb.writeln('  视角：${sh['pov'] ?? ''}');
        sb.writeln('  投放信息：${sh['info'] ?? ''}');
        sb.writeln('  意图：${sh['intent'] ?? ''}');
        sb.writeln('  转场：${sh['transition'] ?? ''}');
        sb.writeln('  篇幅：${sh['length'] ?? ''}');
        sb.writeln('  文笔节奏：${sh['prose_style'] ?? ''}');
        // v218：语感锚
        sb.writeln('  语感锚：${(sh['voice'] ?? '').toString().isNotEmpty ? sh['voice'] : '（旧数据缺失——从焦点/投放信息自行判断原文腔调，同腔调改写禁止文艺加戏）'}');
        // v219：笔墨配额
        sb.writeln('  笔墨配额：${(sh['ink'] ?? '').toString().isNotEmpty ? sh['ink'] : '（旧数据缺失——按焦点与意图判断主次，主要内容占六成以上）'}');
        sb.writeln('  功能抽象：${sh['abstract'] ?? '（缺失，按焦点提炼）'}');
      }
    }
    sb.writeln();
    sb.writeln('## ⚠️ 语感锚铁律');
    sb.writeln('原著voice的抽象三段（修饰密度|句式|语域）照抄进新分镜，例句部分丢弃（例句只用于理解腔调，禁止搬运例句文字）。改写内容时行文腔调必须符合语感锚——');
    sb.writeln('锚是"极简|短句口语|俚俗"时投放信息也只能用同样糙直的口语。');
    sb.writeln('反例警示：原著"李大开\"诶\"一声叫住和尚"→写成"李大开缓缓抬起带着扳指的手，轻声叫住了和尚"=AI文艺腔灾难，禁止。');
    sb.writeln('原著没写的动作细节/道具/神态一律不准凭空添加。');
    sb.writeln('## ⚠️ 笔墨配额铁律');
    sb.writeln('新分镜的ink按改编后内容**重新设计**（格式"内容A约N字·内容B约N字"）——原著ink只作注意力权重思想参照（主次分明、禁平均用力），字数按新内容实际构成重新分配，禁止照抄原著数值。');
    sb.writeln('AI的本能是平均用力，配额就是矫正。intent=铺垫→克制；intent=高潮→打透但同一爽点不打转；intent=钩子→写完就停。');
    sb.writeln();
    sb.writeln();
    sb.writeln('请为已生成条目中的每个新场景填充分镜明细（逐镜转换原著对应场景的分镜骨架，内容以新场景+声明为准；每个分镜输出含语感(Voice)行）。');
    sb.writeln();
    sb.writeln('## ⚠️ 改编要求硬约束（与原著骨架冲突时以它为准）');
    sb.writeln('- 用户改编要求/场景概述里的每个事实（行为方式/责任归属/物品真伪/因果顺序/人物位置关系）都是硬约束，禁止为贴合原著分镜骨架扭曲它们');
    sb.writeln('- 输出前逐镜自检：改编要求涉及本场景的每个事实是否已正确体现在对应分镜？谁借谁的摊、演示用的是真品还是仿品、谁掉包谁问责——这些错了就是改编失败');
    sb.writeln('- ⚠️ 数量自检：输出分镜数必须=原著该场景分镜数（第N镜对应第N原著镜）。发现某镜内容放不进对应功能位=前面概述/声明的表述问题，**调整该镜的内容写法来适配功能位**（保持同姿态同节拍：吐槽位仍是吐槽、投喂位仍是投喂），**禁止砍镜合并来"解决"**');
    return sb.toString();
  }

  /// buildWBDeduceUserPrompt — 推演模式用户提示词：功能骨架+新设定要求（不发原著内容层）
  static String buildWBDeduceUserPrompt(
    dynamic arcItem,
    dynamic arcIdx,
    dynamic totalArcs,
    dynamic requirements,
    dynamic sceneReqs, {
    List<WorldbuildingSystem>? worldbuildingSystems,
    String arcDeclaration = '',
  }) {
    final item = arcItem is Map ? arcItem : <String, dynamic>{};
    final arc = (item['analysis']?['arc'] ?? item['arc'] ?? item) as Map? ?? {};
    final arcNum = (arcIdx is int ? arcIdx : 0) + 1;
    final arcKey =
        item['scanArc']?['number']?.toString() ??
        arc['number']?.toString() ??
        arcNum.toString();
    final sceneReqsMap = sceneReqs is Map ? sceneReqs : <String, dynamic>{};

    final sb = StringBuffer();
    sb.writeln('## 任务（推演模式）');
    sb.writeln(
      '以下是原著弧线$arcNum 的功能骨架。请结合用户的新设定，按功能骨架推演出一个全新的故事，并制作成 SillyTavern 世界书条目。',
    );
    sb.writeln('骨架只提供结构与功能，不提供原著内容——推演出的内容必须是全新故事，与原著零重叠。');
    sb.writeln(
      '⚠️ 骨架的分镜维度里没有焦点(Focus)/投放信息(Info)——这是故意隐去的（内容层防山寨），推演时你必须**自行推演**填入：该分镜在新故事里画面聚焦什么人/物/事；投放信息用**抽象概括的陈述句**（如"读者得知主角对行业行情一无所知"，30字以内，禁止正文式情节叙述）。维度可以换内容，**不可省略维度本身**。',
    );
    sb.writeln();

    if (requirements != null && requirements.toString().isNotEmpty) {
      sb.writeln('## 用户新设定与改编要求（优先级：场景要求 > 弧线要求 > 全局要求）');
      sb.writeln(requirements);
      sb.writeln();
    } else {
      sb.writeln('⚠️ 用户没有输入新设定。请根据骨架功能自行推演一个全新的故事设定，并生成世界书。');
      sb.writeln();
    }

    // 弧线改编声明（改编页预生成，正式改编的指导——遵守声明细节）
    if (arcDeclaration.isNotEmpty) {
      sb.writeln('## 弧线改编声明（必须严格遵守的指导书——声明中的名称/内容均为改编要求即新设定，其中名称是新故事名称，不是原著名称，禁止映射回原著或当原著处理）');
      sb.writeln(arcDeclaration);
      sb.writeln();
    }

    _writeArcSkeletonBlock(sb, arc, arcNum, arcKey, sceneReqsMap);

    sb.writeln('## 输出要求');
    sb.writeln('请按推演结果生成 SillyTavern 世界书条目。');
    if (arcIdx == 0) {
      sb.writeln(
        '首先生成一个"世界概览"常驻条目（constant:true, order:200），包含新故事的主线、支线和弧线列表。',
      );
    }
    sb.writeln('然后生成1条弧线条目（⚠️两步制第一步：本步只生成场景框架+弧线总结，不生成分镜明细）。');
    sb.writeln('第一步条目content结构：');
    sb.writeln('1. 弧线$arcNum概述：（50-150字，放最前面）');
    sb.writeln('2. 全部场景框架（每个场景只有场景头两行，不含分镜）：');
    sb.writeln('   场景N：推演后新场景标题（第X-Y章）← 章节范围原样照抄原著对应场景，禁止自编/省略');
    sb.writeln('   概述：场景概述20-50字（推演的新故事内容）');
    sb.writeln('3. 场景之后依次输出完整弧线总结（⚠️十件套一项不能少——概述+世界观设定+人设（含映射表）+矛盾冲突+伏笔+弧线功能+不可逆变化+情绪曲线+作者脑洞+笔墨癖好，按新设定推演）：');
    sb.writeln('【世界观设定】10个体系每个必须各写一条（未涉及写"本弧线未涉及"），格式：[体系名] 新设定规则（功能：目的）');
    sb.writeln('【人设】区结构：第一部分=角色映射表（每行"原著名→新名（定位）"，列全原著全部角色，主角必须在列）；第二部分=各新角色详情（新姓名+身份+定位+性格特征，规模参照骨架角色结构）');
    sb.writeln('【矛盾冲突】冲突类型+描述（新故事冲突）');
    sb.writeln('【伏笔】伏笔内容+种下位置+预期回报');
    sb.writeln('【弧线功能】本弧线叙事功能');
    sb.writeln('【不可逆变化】弧线结束后的永久性转折');
    sb.writeln('【情绪曲线】情绪轨迹如"低谷→希望→兴奋→满足"');
    sb.writeln('【作者脑洞】新故事体现的核心脑洞类别：具体内容（2-4条）');
    sb.writeln('⚠️ 分镜明细由第二步"填充分镜"单独生成，本步禁止输出分镜行。');
    sb.writeln(
      '分镜的焦点/镜头类型/视角/投放信息参考骨架中的原著值推演改编（不照抄，功能等价替换），其中投放信息(Info)保持抽象概括的陈述句、禁止正文式情节叙述；意图/转场/篇幅/文笔节奏从骨架继承，功能照抄。',
    );
    sb.writeln('**key必须包含"弧线$arcNum"**');
    sb.writeln('⚠️ 条目comment必须为"弧线$arcNum：新故事标题"格式，作为条目显示的编号+标题');
    // 世界观体系设定约束（推演时参照原书规则+功能，遵守改编后设定）
    if (worldbuildingSystems != null && worldbuildingSystems.isNotEmpty) {
      sb.writeln('## 世界观体系设定（推演时必须遵守改编后设定）');
      sb.writeln('以下是原书的世界观规则及其功能目的，以及改编后的设定。推演新内容时必须遵守改编后设定：');
      sb.writeln(
        '⚠️ 条目的【世界观设定】必须包含全部10个体系，每个体系各写一条——上面的体系参照是结构层素材（可换皮继承：换名称换数值保结构功能），**禁止省略任何体系**。参照里没有的体系按新设定自行推演一条：',
      );
      sb.writeln(
        '经济体系/修炼境界体系/功法/技能体系/社会/政治体系/地理/世界体系/法宝物品体系/丹药灵草体系/种族生物体系/组织势力体系/历史传说体系',
      );
      sb.writeln();
      for (final s in worldbuildingSystems) {
        sb.writeln('### ${s.name}体系');
        if (s.originalRules.isNotEmpty) {
          sb.writeln('原书规则：');
          sb.writeln(s.originalRules);
        }
        if (s.functions.isNotEmpty) {
          sb.writeln('功能目的：');
          sb.writeln(s.functions);
        }
        if (s.adaptedRules.isNotEmpty) {
          sb.writeln('改编后设定：');
          sb.writeln(s.adaptedRules);
        }
        sb.writeln();
      }
    }
    sb.writeln('严格按 JSON 格式输出，不要有额外文字。');
    return sb.toString();
  }

  /// v431：全局场景划分（章流窗口版）——场景脱离弧线独立划分，
  /// 弧线之后由分组扫描负责。句级精度=end_text链式切片（v320机制原样）
  static String buildGlobalSceneSystemPrompt() {
    return '你是一位资深网文编辑。你的任务：对给出的连续章节原文划分场景。'
        '场景=按地点/时间连续性划分的叙事单元，与弧线无关，只看叙事连续性。\n\n'
        '场景切换标志（以时空和视角为主）：\n'
        '1. 地点变了（硬信号）\n'
        '2. 时间跳了（硬信号，如"三天后""翌日"）\n'
        '3. 视角切了（硬信号）——叙事视角从一个人物切到另一个人物（哪怕地点没变）\n'
        '4. 叙事焦点转移（弱信号）——仅当同时伴随时空跳跃时才切场景；同一时空内的事件推进、话题转换、矛盾升级是同一场景内的正常叙事发展\n\n'
        '**非切换信号（这些情况必须留在同一场景内）：**\n'
        '- 同一地点内的连续对话（哪怕换了说话人、换了话题）\n'
        '- 同一时空中的动作/打斗/心理/多角色互动延续\n'
        '- 插入的环境描写或回忆闪回结束后回到原叙事\n'
        '- 章节结束但叙事在继续（切章≠切场景）\n'
        '- 仅话题/事件焦点变了但人还在原地（弱信号不切）\n'
        '- **每个闭合点必须单独成条**：前一事件已收束（拿到东西/达成结果/离开现场）后，即使视角人物不变，后续新事件也是新场景——禁止把两个闭合场景合进一条输出\n\n'
        '**场景正文锚点（end_text）：**除最后一个场景外，每个场景必须输出end_text——本场景结束处的分界原句，从原文同一自然段内逐字摘抄20-40字（该句含之前归本场景），不要跨段、不要增删改字和标点，优先选含人名/动作的独特句子。确定候选分界句后，必须执行**段落级迭代验证**：以自然段为单位往后逐段检查——每读一个完整自然段，判断该段属于哪个场景（地点/时间/事件/视角）。若该段仍是本场景的叙事，说明分界句定早了，必须向后继续找下一个候选分界句；重复此过程直到某自然段起确实进入了下一场景，分界句必须定在该切换段之前的最后一个本场景句。**最后一个场景也必须输出end_text**（本窗口结束处的收束句——它是与下一批章节的衔接锚点；若本窗口到章末自然结束，end_text=窗口最后一句）\n\n'
        '**summary要求（供后续弧线分组判定，信息必须显形）：**\n'
        '- 本场景的视角人物是谁（开头标明，如"魏索视角："）\n'
        '- 登场的关键角色\n'
        '- 发生了什么事件、有无结果/收束\n'
        '- 与上一场景相比视角/事件是否切换\n\n'
        'chapter_range格式为"第X-Y章"或"第X章"（一律用阿拉伯数字）。\n\n'
        '**changes要求（关键变化/得失，供弧线概述与闭合判断）：**每个场景输出changes——本场景中角色的关键得失/变化，10-30字具体化（如"获得火凤肚兜""与姬雅达成合作""得知身世真相"）。无实质变化的场景填""。\n\n'
        '只输出纯JSON：{"scenes": [{"name": "场景名", "summary": "视角人物:事件+结果", "focus": "视角人物名", "changes": "关键变化/得失", "chapter_range": "第X-Y章", "end_text": "分界原句"}]}\n\n';
  }

  static String buildGlobalSceneUserPrompt({
    required String windowText,
    required int fromChapter,
    required int toChapter,
    String? prevTail,
  }) {
    final bridge = (prevTail == null || prevTail.isEmpty)
        ? ''
        : '\n\n【衔接提示】上一批内容的最后场景（未收束）以下面这句结束：\n"$prevTail"\n本批原文从该句之后继续。**continuation=true 的唯一条件：本批第一个字符起就是上一场景进行中叙事的直接延续（同一动作/对话进行到一半被切走）。若开头任何一点像新场景（新动作开启/收束后新事件/视角地点任一变化），一律正常新起场景。宁可错拆成两条，不可错并。**不要再把衔接句之前的内容划进来。\n';
    return '请对以下第$fromChapter-$toChapter章原文划分场景。\n\n'
        '要求：\n'
        '- 场景按原文顺序输出，chapter_range必须落在本批章节范围内\n'
        '- 除最后一个场景外每个场景输出end_text（逐字摘抄20-40字）；最后一个场景的end_text=本批末尾收束句（衔接锚点）\n'
        '- summary开头标明视角人物，事件与结果写清楚\n\n'
        '$bridge\n原文如下：\n\n$windowText';
  }

  /// v474：弧线零件提取（分组后逐弧线精修）——输入=该弧线原文切片，
  /// 产出=全套弧线零件（对齐旧版"划分即提取"的信息量）
  static String buildArcPartsSystemPrompt() {
    return '你是一位资深网文编辑。给定一条弧线的原文切片，完成两件事：重写高质量弧线概述+提取全套弧线零件。\n\n'
        '**0. 弧线概述（arc_summary，必填禁省略）**：从原文切片提炼——不是剧情复述，而是主角处境的变化轨迹：'
        '一连串关键变化（得到什么/失去什么/关系怎么变）逐环推进，最终落定在一个明确的不可逆变化上收束。'
        '句式："主角从【起点状态】出发，经过【关键变化1】、【关键变化2】，最终【落定的不可逆变化——如达成合作约定/收入稳定/正式组队/突破完成】，人生进入新阶段"。'
        '2-4句话，具体到人名/物品/事件，落定必须是确定完成的（"达成约定"而不是"发现机会"）。输出自查：没有arc_summary键=不完整。\n\n'
        '**1. 人设（characters）**：弧线中登场或有关键表现的角色：角色名、身份描述、定位（主角/盟友/反派/路人/导师）、性格特征。\n\n'
        '**2. 矛盾冲突（conflicts）**：核心冲突，含冲突类型（人vs人/人vs环境/人vs社会/内心冲突）和描述。\n\n'
        '**3. 伏笔（foreshadowing）**：种下或回收的伏笔：内容、种下位置（哪一章）、预期回报（无则"待回收"）。\n\n'
        '**4. 弧线功能（arc_functions）**：在整部小说中的叙事功能。\n\n'
        '**5. 不可逆变化（irreversible_changes）**：弧线结束后永久性的关键转折。\n\n'
        '**6. 情绪曲线（emotional_curve）**：读者/主角情绪轨迹，如「低谷→希望→兴奋→满足」。\n\n'
        '**7. 作者脑洞（author_fantasy）**：作者反复铺陈、明显投入的具体幻想内容。3-5条，格式「类别：具体内容（出处举例）」。落到具体类别（捡漏文化/知识变现/冤家搭档/以小博大/因祸得福等），不笼统。\n\n'
        '**8. 笔墨癖好（ink_hobby，必填禁省略）**：作者注意力画像——{"痴迷点":"跨场景反复停留的内容类型","快进点":"一笔带过的类型","啰嗦点":"反复交代的细节类型"}。输出自查：没有ink_hobby键=不完整。\n\n'
        '**9. 文风指纹（style_dna，v640，必填禁省略）**：从本弧线原文切片**统计**原作者笔法量化特征（数出来，不是印象）：平均句长、短句占比（≤10字）、动词密度（每句动词数）、对话占比、形容词频率（每千字）、"的"字密度（每百字，定语堆叠代理）、语气词频率（啊/呢/吧，高/中/低）、比喻密度（每千字）、段落均长、标点习惯、句类四态占比（叙述/描写/对话/心理）。输出字符串行格式：【文风指纹】平均句长14字；短句占比45%；动词密度2.1；对话占比35%；形容词频率8；"的"字密度6；语气词频率(中)；比喻密度3；段落均长90字；标点：省略号高频；句类四态：叙述40|描写25|对话25|心理10。这是AI写作时对照施工的硬指标——没有它会退回默认AI文风。输出自查：没有style_dna键=不完整。\n\n**10. 世界观设定facts（worldbuilding_facts）**：10体系每项至少一条fact（经济/修炼境界/功法技能/社会政治/地理世界/法宝物品/丹药灵草/种族生物/组织势力/历史传说；确实未涉及则rule填"本弧线未涉及"）。每条含system/text/rule/function。\n\n'
        '只输出纯JSON（不要markdown）：{"arc_summary": "高质量弧线概述", "characters": [...], "conflicts": [...], "foreshadowing": [...], "arc_functions": [...], "irreversible_changes": "...", "emotional_curve": "...", "author_fantasy": [...], "ink_hobby": {...}, "style_dna": "【文风指纹】平均句长14字；短句占比45%；动词密度2.1；对话占比35%；形容词频率8；\"的\"字密度6；语气词频率(中)；比喻密度3；段落均长90字；标点：省略号高频；句类四态：叙述40|描写25|对话25|心理10", "worldbuilding_facts": [...]}\n\n';
  }

  static String buildArcPartsUserPrompt({
    required String arcTitle,
    required String arcSummary,
    required String arcText,
  }) {
    return '弧线「$arcTitle」的原文切片如下，请生成高质量弧线概述并提取全套弧线零件（按系统提示的JSON格式输出）：\n\n$arcText';
  }

}


